<script lang="ts">
 import {library} from '../../library/store.svelte';import {engine} from '../../bridge/engine.svelte';import {practice} from './practice.svelte';import AriaSymbol from './AriaSymbol.svelte';
 let draft=$state<number|null>(null);
 const shown=$derived(draft??engine.tempoMultiplier);
 const written=$derived.by(()=>{engine.changeSeq;return engine.playbackInfo().bpm||0;});
 function speed(value:number){draft=null;engine.setTempoMultiplier(value);if(library.current?.id)localStorage.setItem('Aria.PracticeSpeed.'+library.current.id,String(value));}
 function reset(){speed(1);practice.setBars(0);if(engine.action('metronome').checked)engine.dispatch('metronome');if(engine.action('countin').checked)engine.dispatch('countin');}
</script>
<div class="aria-practice"><h2>播放与练习</h2><section><label class="metronome"><span><strong>节拍器</strong><small>播放时发出节拍声</small></span><input aria-label="节拍器" type="checkbox" checked={engine.action('metronome').checked} onchange={()=>engine.dispatch('metronome')}/></label></section><section><div class="speed-title"><span><strong>练习速度</strong><small>仅用于此乐谱 · 相对于谱面速度</small></span><span class="speed-value"><b>{Math.round(shown*100)}%</b>{#if written>0}<small>{Math.round(written*shown)} 拍／分</small>{/if}</span></div><input class="speed-slider" aria-label="练习速度" type="range" min=".25" max="1.5" step=".05" value={shown} oninput={e=>{const v=Number(e.currentTarget.value);draft=Math.abs(v-1)<.04?1:v;}} onchange={()=>speed(shown)}/><div class="range-label"><span>25%</span><span>150%</span></div><div class="speed-presets">{#each [.5,.7,.85,1] as value}<button class:chosen={Math.abs(shown-value)<.001} onclick={()=>speed(value)}>{Math.round(value*100)}%</button>{/each}</div></section><section><strong>预备拍</strong><small>正式播放前发出节拍声</small><div class="count-presets">{#each [[0,'关闭'],[1,'一小节'],[2,'两小节']] as [value,label]}<button class:chosen={practice.bars===value} onclick={()=>practice.setBars(Number(value))}>{label}</button>{/each}</div><p>预备拍跟随练习速度和拍号，仅在开始播放时响起，循环反复时不会重复。</p></section><footer><button onclick={reset}><AriaSymbol name="arrow.counterclockwise" size={15}/>重置</button><small>更改将自动生效</small></footer></div>
<style>.aria-practice{width:100%;}.aria-practice h2{font-size:17px;font-weight:700;padding:16px 18px 12px;border-bottom:.5px solid var(--aria-line);}.aria-practice section{padding:14px 18px;border-bottom:.5px solid var(--aria-line);}.aria-practice strong{font-size:16px;font-weight:600;}.aria-practice small{display:block;font-size:13px;color:var(--aria-muted);margin-top:2px;}.metronome,.speed-title{display:flex;align-items:center;justify-content:space-between;gap:8px;}.metronome input{width:42px;height:24px;accent-color:var(--aria-active);}.speed-value{text-align:right;}.speed-value b{font-size:26px;line-height:1.2;font-variant-numeric:tabular-nums;}.speed-slider{width:100%;accent-color:var(--aria-active);margin:14px 0 0;}.range-label{display:flex;justify-content:space-between;font-size:12px;color:var(--aria-muted);margin:2px 0 12px;}.speed-presets,.count-presets{display:flex;gap:8px;}.speed-presets button,.count-presets button{flex:1;min-height:36px;min-width:0;border:0;border-radius:9px;background:color-mix(in srgb, var(--aria-active) 9%, transparent);color:var(--aria-active);font-size:14px;font-weight:600;}.speed-presets .chosen,.count-presets .chosen{background:var(--aria-active);color:var(--aria-on-active);}.count-presets{margin-top:10px;gap:6px;}.count-presets button{background:var(--aria-fill);color:var(--aria-ink);}.aria-practice p{font-size:12px;color:var(--aria-muted);margin-top:10px;}.aria-practice footer{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 18px;}.aria-practice footer button{display:flex;gap:6px;align-items:center;min-height:36px;padding:0 12px;border:0;border-radius:9px;background:var(--aria-fill);color:var(--aria-active);font-size:14px;font-weight:600;}.aria-practice footer small{font-size:12px;white-space:nowrap;}</style>
